using Godot;
using System;

namespace ApexGP24;

public static class ProceduralMaterialFactory
{
    public static StandardMaterial3D CreateAsphaltMaterial()
    {
        var mat = new StandardMaterial3D
        {
            AlbedoColor = Colors.White,
            Roughness = 0.68f,
            Metallic = 0.06f,
            Uv1Scale = new Vector3(1.0f, 1.0f, 1.0f)
        };

        Texture2D extColor = AssetLoader3D.TryLoadTexture("Asphalt PBR",
            "res://assets/textures/asphalt_color.jpg",
            "res://assets/textures/asphalt_color.png");
        if (extColor != null)
        {
            mat.AlbedoTexture = extColor;
            Texture2D extNorm = AssetLoader3D.TryLoadTexture("Asphalt PBR",
                "res://assets/textures/asphalt_normal.jpg",
                "res://assets/textures/asphalt_normal.png");
            if (extNorm != null)
            {
                mat.NormalEnabled = true;
                mat.NormalTexture = extNorm;
                mat.NormalScale = 0.75f;
            }
            Texture2D extRough = AssetLoader3D.TryLoadTexture("Asphalt PBR",
                "res://assets/textures/asphalt_roughness.jpg",
                "res://assets/textures/asphalt_roughness.png");
            if (extRough != null)
            {
                mat.RoughnessTexture = extRough;
            }
            return mat;
        }

        const int sz = 512;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var normImg = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var roughImg = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var rng = new Random(2026);
        float[,] hMap = new float[sz, sz];

        for (int y = 0; y < sz; y++)
        {
            float vWave = Mathf.Sin((y / (float)sz) * Mathf.Tau * 2.0f) * 0.012f;
            for (int x = 0; x < sz; x++)
            {
                float u = x / (float)(sz - 1);
                float grooveL = Mathf.Exp(-Mathf.Pow((u - 0.34f) * 8.0f, 2.0f)) * 0.068f;
                float grooveR = Mathf.Exp(-Mathf.Pow((u - 0.66f) * 8.0f, 2.0f)) * 0.068f;
                float grooveTotal = grooveL + grooveR;
                float fine = ((float)rng.NextDouble() - 0.5f) * 0.072f;
                float streak = Mathf.Sin((u * 38f) + vWave * 6f) * 0.008f;
                hMap[x, y] = fine + streak;

                bool edgeLine = (u < 0.025f || u > 0.975f);
                if (edgeLine)
                {
                    img.SetPixel(x, y, new Color(0.95f, 0.96f, 0.98f));
                    roughImg.SetPixel(x, y, new Color(0.45f, 0.45f, 0.45f));
                }
                else
                {
                    // Rubbered grooves are darker & slightly glossier (lower roughness -> crisp sunlit tarmac sheen!)
                    float v = Mathf.Clamp(0.24f - grooveTotal + fine + streak, 0.09f, 0.36f);
                    img.SetPixel(x, y, new Color(v, v * 1.03f, v * 1.11f));
                    float rVal = Mathf.Clamp(0.76f - grooveTotal * 2.8f + fine * 0.8f, 0.42f, 0.88f);
                    roughImg.SetPixel(x, y, new Color(rVal, rVal, rVal));
                }
            }
        }

        GenerateNormalMapFromHeight(hMap, sz, 5.2f, normImg);
        img.GenerateMipmaps();
        normImg.GenerateMipmaps();
        roughImg.GenerateMipmaps();
        mat.AlbedoTexture = ImageTexture.CreateFromImage(img);
        mat.NormalEnabled = true;
        mat.NormalTexture = ImageTexture.CreateFromImage(normImg);
        mat.NormalScale = 0.62f;
        mat.RoughnessTexture = ImageTexture.CreateFromImage(roughImg);
        mat.Roughness = 1.0f;
        return mat;
    }

    public static StandardMaterial3D CreateGrassMaterial()
    {
        var mat = new StandardMaterial3D
        {
            AlbedoColor = Colors.White,
            Roughness = 0.92f,
            Metallic = 0.0f,
            Uv1Scale = new Vector3(48.0f, 48.0f, 1.0f)
        };

        Texture2D extColor = AssetLoader3D.TryLoadTexture("Grass PBR",
            "res://assets/textures/grass_color.jpg",
            "res://assets/textures/grass_color.png");
        if (extColor != null)
        {
            mat.AlbedoTexture = extColor;
            Texture2D extNorm = AssetLoader3D.TryLoadTexture("Grass PBR",
                "res://assets/textures/grass_normal.jpg",
                "res://assets/textures/grass_normal.png");
            if (extNorm != null)
            {
                mat.NormalEnabled = true;
                mat.NormalTexture = extNorm;
            }
            return mat;
        }

        const int sz = 128;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var normImg = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var rng = new Random(404);
        float[,] hMap = new float[sz, sz];

        for (int y = 0; y < sz; y++)
        {
            bool stripe = ((y / 16) % 2) == 0;
            for (int x = 0; x < sz; x++)
            {
                float n = ((float)rng.NextDouble() - 0.5f) * 0.08f;
                hMap[x, y] = n;
                float sBoost = stripe ? 0.025f : -0.020f;
                float r = Mathf.Clamp(0.16f + sBoost + n * 0.6f, 0.06f, 0.34f);
                float g = Mathf.Clamp(0.35f + sBoost * 1.4f + n, 0.14f, 0.52f);
                float b = Mathf.Clamp(0.13f + sBoost * 0.4f + n * 0.5f, 0.05f, 0.24f);
                img.SetPixel(x, y, new Color(r, g, b));
            }
        }

        GenerateNormalMapFromHeight(hMap, sz, 3.2f, normImg);
        img.GenerateMipmaps();
        normImg.GenerateMipmaps();
        mat.AlbedoTexture = ImageTexture.CreateFromImage(img);
        mat.NormalEnabled = true;
        mat.NormalTexture = ImageTexture.CreateFromImage(normImg);
        mat.NormalScale = 0.45f;
        return mat;
    }

    public static StandardMaterial3D CreateGravelMaterial()
    {
        var mat = new StandardMaterial3D
        {
            AlbedoColor = Colors.White,
            Roughness = 0.94f,
            Metallic = 0.0f,
            Uv1Scale = new Vector3(1.0f, 1.0f, 1.0f)
        };

        Texture2D extColor = AssetLoader3D.TryLoadTexture("Gravel PBR",
            "res://assets/textures/gravel_color.jpg",
            "res://assets/textures/gravel_color.png");
        if (extColor != null)
        {
            mat.AlbedoTexture = extColor;
            Texture2D extNorm = AssetLoader3D.TryLoadTexture("Gravel PBR",
                "res://assets/textures/gravel_normal.jpg",
                "res://assets/textures/gravel_normal.png");
            if (extNorm != null)
            {
                mat.NormalEnabled = true;
                mat.NormalTexture = extNorm;
            }
            return mat;
        }

        // Authentic raked FIA corduroy gravel trap texture with pebbles & ridges
        const int sz = 128;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var normImg = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var rng = new Random(808);
        float[,] hMap = new float[sz, sz];

        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                float furrow = Mathf.Sin((x / (float)sz) * Mathf.Tau * 6.0f) * 0.06f;
                float pebble = ((float)rng.NextDouble() - 0.5f) * 0.14f;
                hMap[x, y] = furrow + pebble * 0.6f;
                float r = Mathf.Clamp(0.68f + furrow + pebble, 0.42f, 0.88f);
                float g = Mathf.Clamp(0.60f + furrow + pebble * 0.9f, 0.36f, 0.78f);
                float b = Mathf.Clamp(0.46f + furrow * 0.8f + pebble * 0.7f, 0.25f, 0.64f);
                img.SetPixel(x, y, new Color(r, g, b));
            }
        }

        GenerateNormalMapFromHeight(hMap, sz, 6.0f, normImg);
        img.GenerateMipmaps();
        normImg.GenerateMipmaps();
        mat.AlbedoTexture = ImageTexture.CreateFromImage(img);
        mat.NormalEnabled = true;
        mat.NormalTexture = ImageTexture.CreateFromImage(normImg);
        mat.NormalScale = 0.80f;
        return mat;
    }

    public static StandardMaterial3D CreateCrowdMaterial()
    {
        const int w = 256;
        const int h = 128;
        var img = Image.CreateEmpty(w, h, false, Image.Format.Rgba8);
        var rng = new Random(2024);

        Color[] shirts =
        {
            new(0.88f, 0.14f, 0.14f), // Ferrari Red
            new(0.95f, 0.96f, 0.98f), // White
            new(0.10f, 0.42f, 0.88f), // Blue
            new(1.00f, 0.78f, 0.12f), // Yellow
            new(1.00f, 0.46f, 0.04f), // Orange Army
            new(0.14f, 0.68f, 0.32f), // Green
            new(0.08f, 0.74f, 0.82f), // Teal
            new(0.18f, 0.22f, 0.32f)  // Navy
        };

        // Concrete seating deck base
        for (int y = 0; y < h; y++)
        {
            for (int x = 0; x < w; x++)
            {
                img.SetPixel(x, y, new Color(0.15f, 0.17f, 0.22f));
            }
        }

        // 12 packed spectator rows with shirts, heads, caps & aisle stairs
        for (int row = 0; row < 12; row++)
        {
            int yBase = row * 10 + 2;
            // Shadow under each bench step
            for (int x = 0; x < w; x++)
            {
                if (yBase + 8 < h) img.SetPixel(x, yBase + 8, new Color(0.06f, 0.07f, 0.10f));
                if (yBase + 9 < h) img.SetPixel(x, yBase + 9, new Color(0.09f, 0.11f, 0.15f));
            }

            for (int x = 2; x < w - 4; x += 4)
            {
                // Concrete staircase aisle every 64 px
                if ((x % 64) < 6)
                {
                    for (int dy = 0; dy < 8; dy++)
                    {
                        for (int dx = 0; dx < 4; dx++)
                        {
                            if (yBase + dy < h) img.SetPixel(x + dx, yBase + dy, new Color(0.32f, 0.35f, 0.40f));
                        }
                    }
                    continue;
                }

                if (rng.NextDouble() < 0.93)
                {
                    Color shirt = shirts[rng.Next(shirts.Length)];
                    Color skin = new Color(0.86f, 0.72f, 0.60f);
                    Color cap = shirts[rng.Next(shirts.Length)];
                    bool hasCap = rng.NextDouble() < 0.40;

                    // Head (2x2)
                    if (yBase + 1 < h)
                    {
                        img.SetPixel(x + 1, yBase, hasCap ? cap : skin);
                        img.SetPixel(x + 2, yBase, hasCap ? cap : skin);
                        img.SetPixel(x + 1, yBase + 1, skin);
                        img.SetPixel(x + 2, yBase + 1, skin);
                    }
                    // Torso / Jersey (3x5)
                    for (int dy = 2; dy < 7 && yBase + dy < h; dy++)
                    {
                        for (int dx = 0; dx < 3; dx++)
                        {
                            img.SetPixel(x + dx, yBase + dy, shirt);
                        }
                    }
                }
            }
        }

        img.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            Roughness = 0.88f,
            Metallic = 0.0f,
            Uv1Scale = new Vector3(2.0f, 1.0f, 1.0f)
        };
    }

    public static StandardMaterial3D CreateBarrierSponsorMaterial()
    {
        const int w = 512;
        const int h = 64;
        var img = Image.CreateEmpty(w, h, false, Image.Format.Rgba8);

        // 4 alternating FIA / Pirelli / Aramco / Apex GP color blocks
        for (int y = 0; y < h; y++)
        {
            for (int x = 0; x < w; x++)
            {
                int panel = x / 128;
                Color bg = panel switch
                {
                    0 => new Color(0.95f, 0.78f, 0.10f), // Pirelli Yellow
                    1 => new Color(0.95f, 0.96f, 0.98f), // White Sponsor
                    2 => new Color(0.86f, 0.10f, 0.10f), // F1 Red
                    _ => new Color(0.07f, 0.44f, 0.34f)  // Aramco Emerald
                };

                // Top metallic rail & lower concrete plinth
                if (y < 6) bg = new Color(0.84f, 0.87f, 0.92f);
                else if (y > 54) bg = new Color(0.55f, 0.59f, 0.65f);
                else if (y >= 24 && y <= 38 && ((x % 128) > 22 && (x % 128) < 106))
                {
                    // Bold contrast graphic bar representing sponsor lettering
                    bool stripeGap = ((x % 16) < 3);
                    if (!stripeGap)
                    {
                        bg = (panel == 0 || panel == 1)
                            ? new Color(0.84f, 0.08f, 0.08f)
                            : new Color(0.97f, 0.98f, 1.0f);
                    }
                }

                // Vertical panel seam
                if ((x % 128) < 2) bg = new Color(0.18f, 0.21f, 0.26f);
                img.SetPixel(x, y, bg);
            }
        }

        img.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            Roughness = 0.52f,
            Metallic = 0.10f,
            CullMode = BaseMaterial3D.CullModeEnum.Disabled
        };
    }

    public static StandardMaterial3D CreateCarbonMaterial(float tileScale = 6.0f)
    {
        var mat = new StandardMaterial3D
        {
            AlbedoColor = Colors.White,
            Roughness = 0.24f,
            Metallic = 0.28f,
            ClearcoatEnabled = true,
            Clearcoat = 0.92f,
            ClearcoatRoughness = 0.12f,
            Uv1Scale = new Vector3(tileScale, tileScale, 1.0f)
        };

        Texture2D extColor = AssetLoader3D.TryLoadTexture("Carbon PBR",
            "res://assets/textures/carbon_color.jpg",
            "res://assets/textures/carbon_color.png");
        if (extColor != null)
        {
            mat.AlbedoTexture = extColor;
            Texture2D extNorm = AssetLoader3D.TryLoadTexture("Carbon PBR",
                "res://assets/textures/carbon_normal.jpg",
                "res://assets/textures/carbon_normal.png");
            if (extNorm != null)
            {
                mat.NormalEnabled = true;
                mat.NormalTexture = extNorm;
            }
            return mat;
        }

        const int sz = 64;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var normImg = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                int cx = x / 8;
                int cy = y / 8;
                bool warp = ((cx + cy) & 3) < 2;
                float lx = (x % 8) / 7.0f;
                float ly = (y % 8) / 7.0f;
                float sheen = warp
                    ? (0.07f + 0.16f * (1.0f - Mathf.Abs(lx - 0.5f) * 2.0f))
                    : (0.04f + 0.09f * (1.0f - Mathf.Abs(ly - 0.5f) * 2.0f));
                img.SetPixel(x, y, new Color(sheen, sheen * 1.07f, sheen * 1.18f));

                float nx = warp ? (lx - 0.5f) * 0.7f : 0f;
                float ny = warp ? 0f : (ly - 0.5f) * 0.7f;
                Vector3 n = new Vector3(nx, ny, 1.0f).Normalized();
                normImg.SetPixel(x, y, new Color(n.X * 0.5f + 0.5f, n.Y * 0.5f + 0.5f, n.Z * 0.5f + 0.5f));
            }
        }
        img.GenerateMipmaps();
        normImg.GenerateMipmaps();
        mat.AlbedoTexture = ImageTexture.CreateFromImage(img);
        mat.NormalEnabled = true;
        mat.NormalTexture = ImageTexture.CreateFromImage(normImg);
        mat.NormalScale = 0.65f;
        return mat;
    }

    public static StandardMaterial3D CreateAlcantaraMaterial()
    {
        const int sz = 64;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var rng = new Random(77);
        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                bool hole = ((x % 6 == 2) && (y % 6 == 2)) || ((x % 6 == 5) && (y % 6 == 5));
                float v = hole ? 0.03f : (0.10f + ((float)rng.NextDouble() - 0.5f) * 0.035f);
                img.SetPixel(x, y, new Color(v, v * 1.03f, v * 1.08f));
            }
        }
        img.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            Roughness = 0.92f,
            Metallic = 0.02f,
            Uv1Scale = new Vector3(4f, 4f, 1f)
        };
    }

    public static StandardMaterial3D CreateNomexGloveMaterial(Color baseColor)
    {
        const int sz = 64;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var rng = new Random(99);
        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                float rib = ((x + y) % 4 == 0) ? 0.06f : 0f;
                float grain = ((float)rng.NextDouble() - 0.5f) * 0.05f;
                float mult = Mathf.Clamp(0.96f + rib + grain, 0.78f, 1.15f);
                img.SetPixel(x, y, new Color(
                    Mathf.Clamp(baseColor.R * mult, 0f, 1f),
                    Mathf.Clamp(baseColor.G * mult, 0f, 1f),
                    Mathf.Clamp(baseColor.B * mult, 0f, 1f)));
            }
        }
        img.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            Roughness = 0.82f,
            Metallic = 0.02f,
            Uv1Scale = new Vector3(3f, 3f, 1f)
        };
    }

    public static StandardMaterial3D CreateCarPaintMaterial(Color baseColor)
    {
        return new StandardMaterial3D
        {
            AlbedoColor = baseColor,
            Metallic = 0.30f,
            Roughness = 0.13f,
            ClearcoatEnabled = true,
            Clearcoat = 1.0f,
            ClearcoatRoughness = 0.045f
        };
    }

    public static StandardMaterial3D CreateTireRubberMaterial()
    {
        const int sz = 128;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var rng = new Random(555);
        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                float band = (x % 16 == 0) ? -0.015f : 0f;
                float v = Mathf.Clamp(0.095f + band + ((float)rng.NextDouble() - 0.5f) * 0.022f, 0.05f, 0.16f);
                img.SetPixel(x, y, new Color(v, v * 1.03f, v * 1.10f));
            }
        }
        img.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            Roughness = 0.48f,
            Metallic = 0.04f,
            ClearcoatEnabled = true,
            Clearcoat = 0.22f,
            ClearcoatRoughness = 0.40f
        };
    }

    public static StandardMaterial3D CreateTireSidewallMaterial(Color compoundColor)
    {
        const int sz = 256;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        float half = sz * 0.5f;
        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                float dx = (x - half) / half;
                float dy = (y - half) / half;
                float r = Mathf.Sqrt(dx * dx + dy * dy);
                float ang = Mathf.Atan2(dy, dx);
                if (ang < 0f) ang += Mathf.Tau;

                Color col = new Color(0.08f, 0.09f, 0.11f);
                if (r > 0.72f && r < 0.81f)
                {
                    bool inMainArc = (ang > 0.25f && ang < 1.85f) || (ang > 3.39f && ang < 4.99f);
                    bool inWhiteTick = (ang > 2.25f && ang < 2.95f) || (ang > 5.39f && ang < 6.09f);
                    if (inMainArc) col = compoundColor;
                    else if (inWhiteTick) col = new Color(0.93f, 0.95f, 0.98f);
                }
                else if (r <= 0.60f && r > 0.54f)
                {
                    col = new Color(0.48f, 0.54f, 0.62f);
                }
                else if (r <= 0.54f && r > 0.14f)
                {
                    float spoke = Mathf.Abs(Mathf.Sin(ang * 3.0f));
                    float v = spoke < 0.10f ? 0.22f : 0.09f;
                    col = new Color(v, v * 1.05f, v * 1.15f);
                }
                else if (r <= 0.14f)
                {
                    col = r < 0.07f ? new Color(0.86f, 0.90f, 0.96f) : new Color(0.85f, 0.12f, 0.14f);
                }

                img.SetPixel(x, y, col);
            }
        }
        img.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            Roughness = 0.42f,
            Metallic = 0.18f
        };
    }

    public static StandardMaterial3D CreateMetalMaterial(Color tint, float roughness = 0.25f)
    {
        return new StandardMaterial3D
        {
            AlbedoColor = tint,
            Metallic = 0.88f,
            Roughness = roughness
        };
    }

    public static StandardMaterial3D CreateEmissiveMaterial(Color color, float energy = 1.6f)
    {
        return new StandardMaterial3D
        {
            AlbedoColor = color,
            EmissionEnabled = true,
            Emission = color,
            EmissionEnergyMultiplier = energy,
            Roughness = 0.20f
        };
    }

    public static StandardMaterial3D CreateVertexColorMaterial(float roughness = 0.80f, bool doubleSided = false)
    {
        return new StandardMaterial3D
        {
            VertexColorUseAsAlbedo = true,
            Roughness = roughness,
            Metallic = 0.05f,
            CullMode = doubleSided ? BaseMaterial3D.CullModeEnum.Disabled : BaseMaterial3D.CullModeEnum.Back
        };
    }

    private static void GenerateNormalMapFromHeight(float[,] hMap, int sz, float strength, Image outImg)
    {
        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                float dx = (hMap[(x + 1) % sz, y] - hMap[(x - 1 + sz) % sz, y]) * strength;
                float dy = (hMap[x, (y + 1) % sz] - hMap[x, (y - 1 + sz) % sz]) * strength;
                Vector3 n = new Vector3(-dx, -dy, 1.0f).Normalized();
                outImg.SetPixel(x, y, new Color(n.X * 0.5f + 0.5f, n.Y * 0.5f + 0.5f, n.Z * 0.5f + 0.5f));
            }
        }
    }
}

