using Godot;
using System;
using System.Collections.Generic;

namespace ApexGP24;

public struct TrackSample
{
    public Vector3 Center;
    public Vector3 Forward;
    public Vector3 Right;
    public float Distance;
    public float Curvature;
}

public partial class TrackBuilder3D : Node3D
{
    public const float TrackHalfWidth = 7.2f;
    public const float KerbWidth = 0.95f;
    public const float RunoffWidth = 7.8f;
    public const float BarrierOffset = TrackHalfWidth + KerbWidth + RunoffWidth;

    public List<TrackSample> Samples { get; } = new();
    public float TotalLength { get; private set; } = 1.0f;

    private readonly List<(Node3D node, float phase)> _wavingFlags = new();
    private readonly List<OmniLight3D> _floodLights = new();
    private StandardMaterial3D _floodLampMat;
    private MeshInstance3D _racingLineMesh;
    private float _windTime = 0f;

    public void BuildCircuit()
    {
        GenerateSplineSamples();
        BuildGroundPlane();
        BuildTrackMeshes();
        BuildStartGantry();
        BuildRacingLineAndBrakingBoards();
        BuildGrandstandsTentsAndScenery();
        BuildHorizonMountainsAndClouds();
    }

    public void SetRacingLineVisible(bool visible)
    {
        if (_racingLineMesh != null) _racingLineMesh.Visible = visible;
    }

    public void SetNightMode(bool isNight)
    {
        if (_floodLampMat != null)
        {
            _floodLampMat.EmissionEnabled = isNight;
            _floodLampMat.EmissionEnergyMultiplier = isNight ? 4.5f : 0.0f;
            _floodLampMat.AlbedoColor = isNight ? new Color(0.95f, 0.98f, 1.0f) : new Color(0.65f, 0.70f, 0.76f);
        }
        foreach (OmniLight3D l in _floodLights)
        {
            l.Visible = isNight;
        }
    }

    public override void _Process(double delta)
    {
        _windTime += (float)delta;
        for (int i = 0; i < _wavingFlags.Count; i++)
        {
            var item = _wavingFlags[i];
            float sway = Mathf.Sin(_windTime * 4.6f + item.phase) * 14.0f;
            item.node.RotationDegrees = new Vector3(0f, sway, Mathf.Cos(_windTime * 3.1f + item.phase) * 4.0f);
        }
    }

    private void GenerateSplineSamples()
    {
        Vector3[] controlPts =
        {
            new Vector3(0f, 0.0f, 0f),
            new Vector3(0f, 0.2f, -150f),
            new Vector3(12f, 1.8f, -280f),
            new Vector3(72f, 3.6f, -335f),
            new Vector3(145f, 4.2f, -310f),
            new Vector3(188f, 2.4f, -225f),
            new Vector3(165f, 1.0f, -135f),
            new Vector3(230f, 2.5f, -55f),
            new Vector3(268f, 3.8f, 55f),
            new Vector3(235f, 2.6f, 170f),
            new Vector3(140f, 1.2f, 225f),
            new Vector3(45f, 0.6f, 200f),
            new Vector3(2f, 0.0f, 118f)
        };

        var rawPts = new List<Vector3>();
        int n = controlPts.Length;
        const int subDiv = 28;

        for (int i = 0; i < n; i++)
        {
            Vector3 p0 = controlPts[(i - 1 + n) % n];
            Vector3 p1 = controlPts[i];
            Vector3 p2 = controlPts[(i + 1) % n];
            Vector3 p3 = controlPts[(i + 2) % n];

            for (int s = 0; s < subDiv; s++)
            {
                float t = s / (float)subDiv;
                rawPts.Add(CatmullRom(p0, p1, p2, p3, t));
            }
        }

        Samples.Clear();
        float accDist = 0f;
        int count = rawPts.Count;

        for (int i = 0; i < count; i++)
        {
            Vector3 prev = rawPts[(i - 1 + count) % count];
            Vector3 curr = rawPts[i];
            Vector3 next = rawPts[(i + 1) % count];

            if (i > 0) accDist += curr.DistanceTo(prev);

            Vector3 fwd = (next - prev).Normalized();
            Vector3 right = fwd.Cross(Vector3.Up).Normalized();
            Vector3 v1 = (curr - prev).Normalized();
            Vector3 v2 = (next - curr).Normalized();
            float crossY = v1.X * v2.Z - v1.Z * v2.X;
            float segLen = Mathf.Max(0.1f, curr.DistanceTo(prev));

            Samples.Add(new TrackSample
            {
                Center = curr,
                Forward = fwd,
                Right = right,
                Distance = accDist,
                Curvature = crossY / segLen
            });
        }

        TotalLength = accDist + rawPts[0].DistanceTo(rawPts[count - 1]);
    }

    private static Vector3 CatmullRom(Vector3 p0, Vector3 p1, Vector3 p2, Vector3 p3, float t)
    {
        float t2 = t * t;
        float t3 = t2 * t;
        return 0.5f * (
            (2.0f * p1) +
            (-p0 + p2) * t +
            (2.0f * p0 - 5.0f * p1 + 4.0f * p2 - p3) * t2 +
            (-p0 + 3.0f * p1 - 3.0f * p2 + p3) * t3
        );
    }

    public TrackSample SampleAtDistance(float dist)
    {
        float wrapped = ((dist % TotalLength) + TotalLength) % TotalLength;
        int count = Samples.Count;
        int lo = 0;
        int hi = count - 1;
        while (lo + 1 < hi)
        {
            int mid = (lo + hi) >> 1;
            if (Samples[mid].Distance <= wrapped) lo = mid;
            else hi = mid;
        }

        int i0 = lo;
        int i1 = (lo + 1) % count;
        float d0 = Samples[i0].Distance;
        float d1 = i1 == 0 ? TotalLength : Samples[i1].Distance;
        float span = Mathf.Max(0.001f, d1 - d0);
        float frac = Mathf.Clamp((wrapped - d0) / span, 0f, 1f);

        TrackSample a = Samples[i0];
        TrackSample b = Samples[i1];
        Vector3 fwd = a.Forward.Lerp(b.Forward, frac).Normalized();
        return new TrackSample
        {
            Center = a.Center.Lerp(b.Center, frac),
            Forward = fwd,
            Right = fwd.Cross(Vector3.Up).Normalized(),
            Distance = wrapped,
            Curvature = Mathf.Lerp(a.Curvature, b.Curvature, frac)
        };
    }

