    private void BuildTrackMeshes()
    {
        var roadSt = new SurfaceTool();
        roadSt.Begin(Mesh.PrimitiveType.Triangles);

        var kerbSt = new SurfaceTool();
        kerbSt.Begin(Mesh.PrimitiveType.Triangles);

        var gravelSt = new SurfaceTool();
        gravelSt.Begin(Mesh.PrimitiveType.Triangles);

        var wallSt = new SurfaceTool();
        wallSt.Begin(Mesh.PrimitiveType.Triangles);

        int count = Samples.Count;
        for (int i = 0; i < count; i++)
        {
            TrackSample a = Samples[i];
            TrackSample b = Samples[(i + 1) % count];
            float dA = a.Distance;
            float dB = i == count - 1 ? TotalLength : b.Distance;
            float vA = dA * 0.10f;
            float vB = dB * 0.10f;

            // 1. Main Asphalt Surface (CW from +Y -> Upward normals & shadows!)
            Vector3 rLA = a.Center - a.Right * TrackHalfWidth + Vector3.Up * 0.04f;
            Vector3 rRA = a.Center + a.Right * TrackHalfWidth + Vector3.Up * 0.04f;
            Vector3 rLB = b.Center - b.Right * TrackHalfWidth + Vector3.Up * 0.04f;
            Vector3 rRB = b.Center + b.Right * TrackHalfWidth + Vector3.Up * 0.04f;
            AddUvQuad(roadSt, rLA, rLB, rRB, rRA, new Vector2(0, vA), new Vector2(0, vB), new Vector2(1, vB), new Vector2(1, vA));

            // 2. Red & White FIA Kerbs + Corner Gravel Traps + Grass Verges + Sponsor Walls!
            bool alt = ((int)(dA / 3.6f) % 2) == 0;
            Color kerbCol = alt ? new Color(0.88f, 0.10f, 0.10f) : new Color(0.96f, 0.97f, 0.99f);
            Color vergeCol = alt ? new Color(0.16f, 0.36f, 0.15f) : new Color(0.13f, 0.32f, 0.13f);
            float curv = a.Curvature;

            foreach (float side in new[] { -1f, 1f })
            {
                Vector3 kInA = a.Center + a.Right * (side * TrackHalfWidth) + Vector3.Up * 0.05f;
                Vector3 kOutA = a.Center + a.Right * (side * (TrackHalfWidth + KerbWidth)) + Vector3.Up * 0.10f;
                Vector3 kInB = b.Center + b.Right * (side * TrackHalfWidth) + Vector3.Up * 0.05f;
                Vector3 kOutB = b.Center + b.Right * (side * (TrackHalfWidth + KerbWidth)) + Vector3.Up * 0.10f;

                Vector3 runOutA = a.Center + a.Right * (side * BarrierOffset) + Vector3.Up * 0.02f;
                Vector3 runOutB = b.Center + b.Right * (side * BarrierOffset) + Vector3.Up * 0.02f;

                Vector3 wBotA = runOutA;
                Vector3 wTopA = runOutA + Vector3.Up * 1.18f;
                Vector3 wBotB = runOutB;
                Vector3 wTopB = runOutB + Vector3.Up * 1.18f;

                // Outside of corners gets authentic raked FIA Gravel Traps!
                bool isGravel = (side < 0 && curv > 0.0045f) || (side > 0 && curv < -0.0045f);
                float wuA = dA * 0.032f;
                float wuB = dB * 0.032f;

                if (side < 0)
                {
                    AddColorQuad(kerbSt, kOutA, kOutB, kInB, kInA, kerbCol);
                    if (isGravel)
                    {
                        AddUvQuad(gravelSt, runOutA, runOutB, kOutB, kOutA, new Vector2(0, vA * 0.6f), new Vector2(0, vB * 0.6f), new Vector2(1.2f, vB * 0.6f), new Vector2(1.2f, vA * 0.6f));
                    }
                    else
                    {
                        AddColorQuad(kerbSt, runOutA, runOutB, kOutB, kOutA, vergeCol);
                    }
                    AddUvQuad(wallSt, wBotA, wBotB, wTopB, wTopA, new Vector2(wuA, 1), new Vector2(wuB, 1), new Vector2(wuB, 0), new Vector2(wuA, 0));
                }
                else
                {
                    AddColorQuad(kerbSt, kInA, kInB, kOutB, kOutA, kerbCol);
                    if (isGravel)
                    {
                        AddUvQuad(gravelSt, kOutA, kOutB, runOutB, runOutA, new Vector2(0, vA * 0.6f), new Vector2(0, vB * 0.6f), new Vector2(1.2f, vB * 0.6f), new Vector2(1.2f, vA * 0.6f));
                    }
                    else
                    {
                        AddColorQuad(kerbSt, kOutA, kOutB, runOutB, runOutA, vergeCol);
                    }
                    AddUvQuad(wallSt, wBotB, wBotA, wTopA, wTopB, new Vector2(wuB, 1), new Vector2(wuA, 1), new Vector2(wuA, 0), new Vector2(wuB, 0));
                }
            }
        }

        roadSt.GenerateNormals();
        roadSt.GenerateTangents();
        AddChild(new MeshInstance3D
        {
            Mesh = roadSt.Commit(),
            MaterialOverride = ProceduralMaterialFactory.CreateAsphaltMaterial()
        });

        kerbSt.GenerateNormals();
        AddChild(new MeshInstance3D
        {
            Mesh = kerbSt.Commit(),
            MaterialOverride = ProceduralMaterialFactory.CreateVertexColorMaterial(0.78f, true)
        });

        gravelSt.GenerateNormals();
        gravelSt.GenerateTangents();
        AddChild(new MeshInstance3D
        {
            Mesh = gravelSt.Commit(),
            MaterialOverride = ProceduralMaterialFactory.CreateGravelMaterial()
        });

        wallSt.GenerateNormals();
        AddChild(new MeshInstance3D
        {
            Mesh = wallSt.Commit(),
            MaterialOverride = ProceduralMaterialFactory.CreateBarrierSponsorMaterial()
        });
    }

