                Position = new Vector3(-side * 0.4f, 8.2f, 0f),
                RotationDegrees = new Vector3(0f, 0f, side * 5f),
                MaterialOverride = roofMat
            });

            // 5 Animated Waving National / Fan Flags along the upper grandstand deck
            for (int f = 0; f < 5; f++)
            {
                float fz = -14.0f + f * 7.0f;
                float fx = side * (-1.5f + (f % 2) * 2.2f);
                float fy = 4.2f + (f % 2) * 1.1f;

