            });
            tent.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(7.1f, 0.28f, 8.8f) },
                Position = new Vector3(0f, 3.05f, 0f),
                MaterialOverride = redTrimMat
            });
        }

        // 3. Multi-Layered Trackside Trees + Night Stadium Floodlight Towers!
        int lightIdx = 0;
        for (float d = 12f; d < TotalLength; d += 32f)
        {
            TrackSample s = SampleAtDistance(d);
            foreach (float side in new[] { -1f, 1f })
            {
                Vector3 treePos = s.Center + s.Right * (side * (BarrierOffset + 19.0f + ((d * 0.37f) % 10f)));
                var tree = new Node3D { Position = treePos };
                AddChild(tree);
                tree.AddChild(new MeshInstance3D
                {
                    Mesh = new CylinderMesh { TopRadius = 0.24f, BottomRadius = 0.38f, Height = 3.6f, RadialSegments = 8 },
                    Position = new Vector3(0f, 1.8f, 0f),
                    MaterialOverride = trunkMat
                });
                tree.AddChild(new MeshInstance3D
                {
                    Mesh = new SphereMesh { Radius = 3.1f, Height = 4.6f, RadialSegments = 10, Rings = 6 },
                    Position = new Vector3(0f, 4.5f, 0f),
                    MaterialOverride = leafDarkMat
                });
                tree.AddChild(new MeshInstance3D
                {
                    Mesh = new SphereMesh { Radius = 2.3f, Height = 3.8f, RadialSegments = 10, Rings = 6 },
                    Position = new Vector3(0.6f * side, 6.2f, 0.4f),
                    MaterialOverride = leafLightMat
                });
            }

            // Stadium Floodlight Tower every 64m (alternating sides)
            if ((lightIdx % 2) == 0)
            {
                float fSide = ((lightIdx / 2) % 2 == 0) ? -1f : 1f;
                var tower = new Node3D
                {
                    Position = s.Center + s.Right * (fSide * (BarrierOffset + 1.8f)),
                    Basis = Basis.LookingAt(s.Forward, Vector3.Up)
                };
                AddChild(tower);

                tower.AddChild(new MeshInstance3D
                {
                    Mesh = new CylinderMesh { TopRadius = 0.16f, BottomRadius = 0.26f, Height = 13.5f, RadialSegments = 8 },
                    Position = new Vector3(0f, 6.75f, 0f),
                    MaterialOverride = poleMat
                });
                tower.AddChild(new MeshInstance3D
                {
                    Mesh = new BoxMesh { Size = new Vector3(2.8f, 1.1f, 0.45f) },
                    Position = new Vector3(-fSide * 1.1f, 13.4f, 0f),
                    RotationDegrees = new Vector3(0f, 0f, fSide * 24f),
                    MaterialOverride = _floodLampMat
                });

                var light = new OmniLight3D
                {
                    Position = new Vector3(-fSide * 3.0f, 11.5f, 0f),
                    LightColor = new Color(0.90f, 0.95f, 1.0f),
                    LightEnergy = 8.5f,
                    OmniRange = 46f,
                    OmniAttenuation = 1.4f,
                    Visible = false
                };
                tower.AddChild(light);
                _floodLights.Add(light);
            }
            lightIdx++;
        }
    }


    private void BuildRacingLineAndBrakingBoards()
    {
        // 1. Dynamic 3D FIA Racing Line Ribbon (Green = Full Throttle, Yellow = Apex/Lift, Red = Brake!)
        var lineSt = new SurfaceTool();
        lineSt.Begin(Mesh.PrimitiveType.Triangles);

        int count = Samples.Count;
        float[] targetSpeed = new float[count];
        for (int i = 0; i < count; i++)
        {
            float absK = Mathf.Abs(Samples[i].Curvature);
            targetSpeed[i] = absK < 0.004f ? 340f : Mathf.Clamp(Mathf.Sqrt(78f / absK) * 3.6f, 95f, 340f);
        }
        // Backward braking envelope (~95m braking zone)
        for (int pass = 0; pass < 2; pass++)
        {
            for (int i = count - 1; i >= 0; i--)
            {
                int next = (i + 1) % count;
                float ds = Mathf.Max(0.5f, Samples[next].Center.DistanceTo(Samples[i].Center));
                float vNext = targetSpeed[next] / 3.6f;
                float vAllow = Mathf.Sqrt(vNext * vNext + 2f * 32f * ds) * 3.6f;
                if (vAllow < targetSpeed[i]) targetSpeed[i] = vAllow;
            }
        }

        for (int i = 0; i < count; i++)
        {
            TrackSample a = Samples[i];
            TrackSample b = Samples[(i + 1) % count];
            float kA = a.Curvature;
            float kB = b.Curvature;

            // Out-In-Out FIA racing line offset
            float offA = Mathf.Clamp(kA * 180f, -TrackHalfWidth * 0.62f, TrackHalfWidth * 0.62f);
            float offB = Mathf.Clamp(kB * 180f, -TrackHalfWidth * 0.62f, TrackHalfWidth * 0.62f);

            float spd = targetSpeed[i];
            float spdNext = targetSpeed[(i + 5) % count];
            Color col = (spd - spdNext > 18f || spd < 155f)
                ? new Color(1.0f, 0.14f, 0.10f, 0.78f)
                : (spd < 235f ? new Color(1.0f, 0.82f, 0.08f, 0.72f) : new Color(0.05f, 0.92f, 0.42f, 0.56f));

            const float halfRibbon = 0.24f;
            Vector3 cA = a.Center + a.Right * offA + Vector3.Up * 0.068f;
            Vector3 cB = b.Center + b.Right * offB + Vector3.Up * 0.068f;
            AddColorQuad(
                lineSt,
                cA - a.Right * halfRibbon,
                cB - b.Right * halfRibbon,
                cB + b.Right * halfRibbon,
                cA + a.Right * halfRibbon,
                col);
        }

        lineSt.GenerateNormals();
        var lineMat = new StandardMaterial3D
        {
            VertexColorUseAsAlbedo = true,
            Transparency = BaseMaterial3D.TransparencyEnum.Alpha,
            ShadingMode = BaseMaterial3D.ShadingModeEnum.Unshaded,
            CullMode = BaseMaterial3D.CullModeEnum.Disabled
        };
        _racingLineMesh = new MeshInstance3D
        {
            Name = "RacingLine3D",
            Mesh = lineSt.Commit(),
            MaterialOverride = lineMat
        };
        AddChild(_racingLineMesh);

        // 2. Authentic FIA 150m / 100m / 50m Braking Marker Boards before heavy corners!
        var boardBg = new StandardMaterial3D { AlbedoColor = new Color(0.96f, 0.97f, 0.99f), Roughness = 0.4f };
        var postMat = ProceduralMaterialFactory.CreateMetalMaterial(new Color(0.20f, 0.24f, 0.30f), 0.4f);
        float lastCornerDist = -200f;

        for (int i = 0; i < count; i++)
        {
            float absK = Mathf.Abs(Samples[i].Curvature);
            if (absK > 0.018f && (Samples[i].Distance - lastCornerDist) > 220f)
            {
                lastCornerDist = Samples[i].Distance;
                float outsideSide = Samples[i].Curvature > 0f ? -1f : 1f;
                int[] markers = { 150, 100, 50 };
                foreach (int m in markers)
                {
                    TrackSample ms = SampleAtDistance(Samples[i].Distance - m);
                    var board = new Node3D
                    {
                        Position = ms.Center + ms.Right * (outsideSide * (TrackHalfWidth + 2.4f)),
                        Basis = Basis.LookingAt(ms.Forward, Vector3.Up)
                    };
                    AddChild(board);

                    board.AddChild(new MeshInstance3D
                    {
                        Mesh = new BoxMesh { Size = new Vector3(0.08f, 1.3f, 0.08f) },
                        Position = new Vector3(0f, 0.65f, 0f),
                        MaterialOverride = postMat
                    });
                    board.AddChild(new MeshInstance3D
                    {
                        Mesh = new BoxMesh { Size = new Vector3(1.15f, 0.65f, 0.08f) },
                        Position = new Vector3(0f, 1.25f, 0f),
                        MaterialOverride = boardBg
                    });
                    board.AddChild(new Label3D
                    {
                        Text = $"{m}",
                        Position = new Vector3(0f, 1.25f, 0.06f),
                        FontSize = 64,
                        PixelSize = 0.0065f,
                        Modulate = new Color(0.06f, 0.08f, 0.12f),
                        OutlineSize = 0
                    });
                }
            }
        }
    }

    private void BuildHorizonMountainsAndClouds()
    {
        // Scenic distant mountain ridge ring around the circuit (adds huge depth & realism!)
        var rng = new Random(909);
        var mtnFarMat = new StandardMaterial3D { AlbedoColor = new Color(0.24f, 0.34f, 0.44f), Roughness = 0.96f };
        var mtnNearMat = new StandardMaterial3D { AlbedoColor = new Color(0.16f, 0.28f, 0.21f), Roughness = 0.94f };
        Vector3 circuitCenter = new Vector3(115f, -2f, -45f);

        for (int i = 0; i < 28; i++)
        {
            float ang = (i / 28f) * Mathf.Tau;
            float dist = 540f + (float)rng.NextDouble() * 140f;
            float h = 42f + (float)rng.NextDouble() * 68f;
            float rad = 75f + (float)rng.NextDouble() * 75f;
            AddChild(new MeshInstance3D
            {
                Mesh = new CylinderMesh { TopRadius = rad * 0.12f, BottomRadius = rad, Height = h, RadialSegments = 7 },
                Position = circuitCenter + new Vector3(Mathf.Cos(ang) * dist, h * 0.42f, Mathf.Sin(ang) * dist),
                MaterialOverride = (i % 2 == 0) ? mtnFarMat : mtnNearMat
            });
        }

        // Soft volumetric cloud puffs drifting high above the horizon
        var cloudMat = new StandardMaterial3D
        {
            AlbedoColor = new Color(0.96f, 0.98f, 1.0f, 0.72f),
            Transparency = BaseMaterial3D.TransparencyEnum.Alpha,
            Roughness = 1.0f
        };
        for (int c = 0; c < 18; c++)
        {
            float ang = (c / 18f) * Mathf.Tau + 0.12f;
            float dist = 420f + (float)rng.NextDouble() * 220f;
            float cy = 115f + (float)rng.NextDouble() * 55f;
            AddChild(new MeshInstance3D
            {
                Mesh = new SphereMesh { Radius = 28f + (float)rng.NextDouble() * 22f, Height = 16f, RadialSegments = 10, Rings = 5 },
                Position = circuitCenter + new Vector3(Mathf.Cos(ang) * dist, cy, Mathf.Sin(ang) * dist),
                Scale = new Vector3(2.4f, 0.55f, 1.2f),
                MaterialOverride = cloudMat
            });
        }
    }

    private static void AddUvQuad(SurfaceTool st, Vector3 a, Vector3 b, Vector3 c, Vector3 d, Vector2 uvA, Vector2 uvB, Vector2 uvC, Vector2 uvD)
    {
        st.SetUV(uvA); st.AddVertex(a);
        st.SetUV(uvB); st.AddVertex(b);
        st.SetUV(uvC); st.AddVertex(c);

        st.SetUV(uvA); st.AddVertex(a);
        st.SetUV(uvC); st.AddVertex(c);
        st.SetUV(uvD); st.AddVertex(d);
    }

    private static void AddColorQuad(SurfaceTool st, Vector3 a, Vector3 b, Vector3 c, Vector3 d, Color col)
    {
        st.SetColor(col); st.AddVertex(a);
        st.SetColor(col); st.AddVertex(b);
        st.SetColor(col); st.AddVertex(c);

        st.SetColor(col); st.AddVertex(a);
        st.SetColor(col); st.AddVertex(c);
        st.SetColor(col); st.AddVertex(d);
    }
}

