    private Camera3D _tCam;
    private SteeringWheelMfd3D _steeringWheel;
    private Node3D _frontLeftSteering;
    private Node3D _frontRightSteering;
    private Node3D _frontLeftSpin;
    private Node3D _frontRightSpin;
    private Node3D _rearLeftSpin;
    private Node3D _rearRightSpin;
    private StandardMaterial3D _brakeGlowMat;
    private StandardMaterial3D _primaryPaintMat;
    private StandardMaterial3D _secondaryPaintMat;
    private Label3D _noseTeamLabel;

    public int LiveryIndex { get; private set; } = 0;
    public F1Livery3D CurrentLivery => Liveries[LiveryIndex];

    public bool IsCockpitCamera { get; private set; } = true;
    public float TrackDistance { get; private set; } = 0f;
    public float TotalDistance { get; private set; } = 0f;
    public float LateralOffset { get; private set; } = 0f;
    public float HeadingOffset { get; private set; } = 0f;
    public float SpeedKmh { get; private set; } = 0f;
    public float SteerAngle { get; private set; } = 0f;
    public float BrakePressure { get; private set; } = 0f;
    public float ErsCharge { get; private set; } = 100f;
    public bool ErsEnabled { get; set; } = false;
    public bool IsOffTrack { get; private set; } = false;
    public bool OnKerb { get; private set; } = false;
    public bool InSlipstream { get; private set; } = false;
    public int CurrentPosition { get; set; } = 16;
    public int CurrentLap { get; private set; } = 1;
    public float CurrentLapTime { get; private set; } = 0f;
    public float BestLapTime { get; private set; } = 999f;

    // Precision Steering Inputs & Settings
    public bool InputLeft { get; set; }
    public bool InputRight { get; set; }
    public float? AnalogSteerTarget { get; set; } = null;
    public bool InputGas { get; set; }
    public bool InputBrake { get; set; }
    public float SteerSensitivity { get; set; } = 1.25f; // 0.80 (Suave) .. 1.55 (Pro)

    private float _wheelRoll = 0f;
    private float _smoothLatG = 0f;
    private float _smoothLongG = 0f;
    private float _smoothBrakeHeat = 0f;
    private float _smoothTireHeat = 0.38f;
    private float _engineRpm = 4200f;
    private float _totalTime = 0f;
    private float _impactLatVel = 0f;

    // Smooth Physics-to-Render Interpolation Pose Buffers (buttery 60/90/120Hz motion!)
    private Vector3 _prevPos;
    private Basis _prevBasis = Basis.Identity;
    private Vector3 _currPos;
    private Basis _currBasis = Basis.Identity;

    public float EngineRpm => _engineRpm;

    public int Gear
    {
        get
        {
            if (SpeedKmh < 82f) return 1;
            if (SpeedKmh < 126f) return 2;
            if (SpeedKmh < 168f) return 3;
            if (SpeedKmh < 208f) return 4;
            if (SpeedKmh < 248f) return 5;
            if (SpeedKmh < 286f) return 6;
            if (SpeedKmh < 320f) return 7;
            return 8;
        }
    }

    public float RpmNormalized => Mathf.Clamp((_engineRpm - 5500f) / 8500f, 0f, 1f);

    public void Initialize(TrackBuilder3D track)
    {
        _track = track;
        BuildCar3D();
        ResetToGrid(12.0f, -2.8f);
    }

    public void ToggleCamera()
    {
        IsCockpitCamera = !IsCockpitCamera;
        _cockpitCam.Current = IsCockpitCamera;
        _tCam.Current = !IsCockpitCamera;
    }

    public void CycleLivery()
    {
        LiveryIndex = (LiveryIndex + 1) % Liveries.Length;
        var liv = CurrentLivery;
        _primaryPaintMat.AlbedoColor = liv.Primary;
        _secondaryPaintMat.AlbedoColor = liv.Secondary;
        _noseTeamLabel.Text = liv.Code;
        _noseTeamLabel.Modulate = liv.Secondary;
        _steeringWheel.UpdateColors(liv.Glove, liv.Secondary);
    }

    public void ResetToGrid(float startDist, float startLane)
    {
        TrackDistance = startDist;
        TotalDistance = startDist;
        LateralOffset = startLane;
        HeadingOffset = 0f;
        SpeedKmh = 0f;
        SteerAngle = 0f;
        BrakePressure = 0f;
        ErsCharge = 100f;
        ErsEnabled = false;
        CurrentLap = 1;
        CurrentLapTime = 0f;
        _smoothLatG = 0f;
        _smoothLongG = 0f;
        _smoothBrakeHeat = 0f;
        _smoothTireHeat = 0.38f;
        _engineRpm = 4200f;
        _impactLatVel = 0f;
        ComputePose(out _currPos, out _currBasis);
        _prevPos = _currPos;
        _prevBasis = _currBasis;
        Position = _currPos;
        Basis = _currBasis;
    }

    private void BuildCar3D()
