        _analogTrack.AddChild(new ColorRect { Color = new Color(1f, 1f, 1f, 0.30f), Position = new Vector2(149, 24), Size = new Vector2(2, 50) });
        _analogKnob = CreateCard(new Vector2(124, 15), new Vector2(52, 68), new Color(0.05f, 0.72f, 0.96f, 0.96f), Colors.White);
