        _steerZone.AddChild(new ColorRect { Color = new Color(0.05f, 0.08f, 0.14f, 0.90f), Position = new Vector2(8, 124), Size = new Vector2(300, 9) });
        _steerZone.AddChild(new ColorRect { Color = new Color(1f, 1f, 1f, 0.45f), Position = new Vector2(157, 124), Size = new Vector2(2, 9) });
        _steerBarFill = new ColorRect { Color = new Color(0.0f, 0.90f, 1.0f), Position = new Vector2(158, 124), Size = new Vector2(0, 9) };
        _steerZone.AddChild(_steerBarFill);

        // 5. BOTTOM-RIGHT: Multi-Touch Pedals (FRENO + GAS) + ERS Button
        (_btnErs, _ersStyle) = CreateAnchoredControlPad(root, 1, 1, 1, 1, -240, -222, -20, -168, "ERS / OVERTAKE", 15, new Color(0.06f, 0.24f, 0.44f, 0.86f), new Color(0.0f, 0.90f, 1.0f));
        (_btnBrake, _brakeStyle) = CreateAnchoredControlPad(root, 1, 1, 1, 1, -258, -152, -142, -22, "FRENO", 18, new Color(0.42f, 0.08f, 0.10f, 0.84f), new Color(1.0f, 0.35f, 0.35f));
        _brakeBarFill = new ColorRect { Color = new Color(1.0f, 0.14f, 0.20f, 0.52f), Position = new Vector2(4, 126), Size = new Vector2(108, 0), MouseFilter = Control.MouseFilterEnum.Ignore };
        _btnBrake.AddChild(_brakeBarFill);
        (_btnGas, _gasStyle) = CreateAnchoredControlPad(root, 1, 1, 1, 1, -128, -162, -20, -22, "GAS", 20, new Color(0.07f, 0.38f, 0.18f, 0.86f), new Color(0.0f, 0.92f, 0.46f));

