using Godot;
using System;
using System.Collections.Generic;
using System.Text;

namespace ApexGP24;

public enum TimeOfDayPreset
{
    Day = 0,
    Sunset = 1,
    Night = 2
}

public partial class MainRaceController : Node3D
{
    private WorldEnvironment _worldEnv;
    private DirectionalLight3D _sunLight;
    private TrackBuilder3D _track;
    private PlayerCar3D _player;
    private F1AudioSynth _audio;
    private readonly List<RivalCar3D> _rivals = new();

    private TimeOfDayPreset _timePreset = TimeOfDayPreset.Day;
    private bool _highQuality = true;
    private bool _racingLineOn = true;

    public bool IsPaused { get; set; } = false;
    public bool RaceStarted => _startCountdown <= 0f;
    public int StartLightsLitCount => Mathf.Clamp(Mathf.CeilToInt((3.4f - _startCountdown) / 0.58f), 0, 5);

    private float _startCountdown = 3.4f;
    private float _raceTime = 0f;
    private readonly List<(string code, float dist, bool isPlayer)> _standings = new();
    private readonly StringBuilder _lbBuilder = new();

    public string CurrentTimeLabel => _timePreset switch
    {
        TimeOfDayPreset.Day => "DÍA",
        TimeOfDayPreset.Sunset => "TARDE",
        _ => "NOCHE"
    };

    public string CurrentQualityLabel => _highQuality ? "ALTA" : "MEDIA";

    public override void _Ready()
    {
        AssetLoader3D.ResetLog();
        SetupEnvironmentAndSun();

        _track = new TrackBuilder3D { Name = "Circuit3D" };
        AddChild(_track);
        _track.BuildCircuit();

        _audio = new F1AudioSynth { Name = "F1AudioSynth" };
        AddChild(_audio);

        _player = new PlayerCar3D { Name = "PlayerCar3D" };
        AddChild(_player);
        _player.Initialize(_track);

        Spawn19Rivals();
        RestartRace();

        var hud = new TouchHud { Name = "TouchHud" };
        AddChild(hud);
        hud.Initialize(_player, this);

        ApplyTimeOfDay(_timePreset);
    }

    private void Spawn19Rivals()
    {
        Color soft = new(0.92f, 0.08f, 0.10f);
        Color med = new(0.98f, 0.82f, 0.08f);
        Color hard = new(0.95f, 0.97f, 1.00f);

        RivalSpec[] grid =
        {
            new() { Code = "VER", RearWingSponsor = "ORACLE",   Primary = new(0.08f, 0.14f, 0.38f), Secondary = new(0.88f, 0.06f, 0.08f), Helmet = new(1.00f, 0.44f, 0.00f), TyreCompound = soft, Skill = 0.99f },
            new() { Code = "NOR", RearWingSponsor = "MCLAREN",  Primary = new(1.00f, 0.48f, 0.02f), Secondary = new(0.10f, 0.12f, 0.16f), Helmet = new(0.82f, 0.98f, 0.08f), TyreCompound = soft, Skill = 0.96f },
            new() { Code = "LEC", RearWingSponsor = "FERRARI",  Primary = new(0.86f, 0.07f, 0.10f), Secondary = new(0.98f, 0.82f, 0.08f), Helmet = Colors.White,              TyreCompound = soft, Skill = 0.96f },
            new() { Code = "PIA", RearWingSponsor = "MCLAREN",  Primary = new(1.00f, 0.48f, 0.02f), Secondary = new(0.10f, 0.12f, 0.16f), Helmet = new(0.16f, 0.72f, 0.96f), TyreCompound = med,  Skill = 0.94f },
