                OutlineSize = 0
            });
        }

        Vector2[] boltPts =
        {
            new(-0.074f, 0.066f), new(0.074f, 0.066f),
            new(-0.082f, 0.016f), new(0.082f, 0.016f),
            new(-0.082f, -0.026f), new(0.082f, -0.026f),
