    private static Label AddMfdLabel(Control parent, string text, Vector2 pos, Vector2 size, int fontSize, Color col, HorizontalAlignment align)
    {
        var lbl = new Label
        {
            Text = text,
            Position = pos,
            Size = size,
            HorizontalAlignment = align,
            VerticalAlignment = VerticalAlignment.Center
        };
        lbl.AddThemeFontSizeOverride("font_size", fontSize);
        lbl.AddThemeColorOverride("font_color", col);
        parent.AddChild(lbl);
        return lbl;
    }

    private void BuildTyreRainbowDial(Vector3 pos, StandardMaterial3D metalMat, StandardMaterial3D darkMat)
    {
        var dial = new Node3D { Position = pos };
        AddChild(dial);

        Color[] segColors =
        {
            new(0.0f, 0.70f, 1.0f),
            new(0.05f, 0.90f, 0.45f),
            new(1.0f, 0.85f, 0.08f),
            new(0.98f, 0.14f, 0.18f),
            new(0.92f, 0.95f, 0.99f),
            new(0.18f, 0.48f, 0.98f)
        };
        for (int s = 0; s < segColors.Length; s++)
        {
            float ang = (s / (float)segColors.Length) * Mathf.Tau;
            dial.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(0.008f, 0.006f, 0.005f) },
                Position = new Vector3(Mathf.Cos(ang) * 0.0155f, Mathf.Sin(ang) * 0.0155f, 0.001f),
                RotationDegrees = new Vector3(0f, 0f, Mathf.RadToDeg(ang)),
                MaterialOverride = new StandardMaterial3D { AlbedoColor = segColors[s], Roughness = 0.30f }
            });
        }
        dial.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = 0.012f, BottomRadius = 0.013f, Height = 0.010f, RadialSegments = 16 },
            RotationDegrees = new Vector3(90f, 0f, 0f),
            MaterialOverride = darkMat
        });
        dial.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = 0.0132f, BottomRadius = 0.0135f, Height = 0.005f, RadialSegments = 16 },
            Position = new Vector3(0f, 0f, -0.001f),
            RotationDegrees = new Vector3(90f, 0f, 0f),
            MaterialOverride = metalMat
        });
        dial.AddChild(new Label3D
        {
            Text = "TYRE",
            Position = new Vector3(0f, 0f, 0.0065f),
            FontSize = 18,
            PixelSize = 0.00030f,
            Modulate = Colors.White,
            OutlineSize = 0
        });
    }

    private void BuildRotaryKnob(Vector3 pos, float radius, Color accent, string label, StandardMaterial3D metalMat, StandardMaterial3D darkMat)
    {
        var knob = new Node3D { Position = pos };
        AddChild(knob);

        knob.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = radius, BottomRadius = radius * 1.06f, Height = 0.010f, RadialSegments = 14 },
            RotationDegrees = new Vector3(90f, 0f, 0f),
            MaterialOverride = metalMat
        });
        knob.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = radius * 0.78f, BottomRadius = radius * 0.80f, Height = 0.012f, RadialSegments = 14 },
            RotationDegrees = new Vector3(90f, 0f, 0f),
            MaterialOverride = new StandardMaterial3D { AlbedoColor = accent, Roughness = 0.32f }
        });
        knob.AddChild(new MeshInstance3D
        {
            Mesh = new BoxMesh { Size = new Vector3(0.0025f, radius * 0.9f, 0.003f) },
            Position = new Vector3(0f, radius * 0.25f, 0.0065f),
            MaterialOverride = darkMat
        });
        knob.AddChild(new Label3D
        {
            Text = label,
            Position = new Vector3(0f, -radius - 0.006f, 0.005f),
            FontSize = 16,
            PixelSize = 0.00028f,
            Modulate = new Color(0.88f, 0.93f, 1.0f),
            OutlineSize = 0
        });
    }

    private void BuildPushButton(Vector3 pos, Color color, string label, StandardMaterial3D metalMat)
    {
        var btn = new Node3D { Position = pos };
        AddChild(btn);

        // Metallic protective shroud ring
        btn.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = 0.0085f, BottomRadius = 0.0092f, Height = 0.007f, RadialSegments = 14 },
            RotationDegrees = new Vector3(90f, 0f, 0f),
            MaterialOverride = metalMat
        });
        // Glowing colored button cap
        btn.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = 0.0062f, BottomRadius = 0.0065f, Height = 0.0095f, RadialSegments = 12 },
            RotationDegrees = new Vector3(90f, 0f, 0f),
            MaterialOverride = new StandardMaterial3D
            {
                AlbedoColor = color,
                EmissionEnabled = true,
                Emission = color,
                EmissionEnergyMultiplier = 0.35f,
