    private void BuildRacingGlove3D(float side, StandardMaterial3D carbonMat, StandardMaterial3D whiteCuffMat)
    {
        var hand = new Node3D { Position = new Vector3(side * 0.152f, -0.012f, 0.010f) };
        AddChild(hand);

        // Sculpted ergonomic palm & back-of-hand shell
        hand.AddChild(new MeshInstance3D
        {
            Mesh = new CapsuleMesh { Radius = 0.032f, Height = 0.105f, RadialSegments = 14, Rings = 6 },
            Position = new Vector3(side * 0.008f, -0.008f, 0.008f),
            RotationDegrees = new Vector3(14f, side * -12f, side * 10f),
            Scale = new Vector3(0.92f, 1.0f, 0.78f),
            MaterialOverride = _gloveMat
        });

        // Molded dark carbon knuckle guard on back of hand
        hand.AddChild(new MeshInstance3D
        {
            Mesh = new BoxMesh { Size = new Vector3(0.044f, 0.022f, 0.012f) },
            Position = new Vector3(side * 0.006f, 0.012f, 0.029f),
            RotationDegrees = new Vector3(0f, side * -12f, side * 8f),
            MaterialOverride = carbonMat
        });

        // 3 Wrapped Fingers curling around outer top/mid wheel grip
        for (int f = 0; f < 3; f++)
        {
            hand.AddChild(new MeshInstance3D
            {
                Mesh = new CapsuleMesh { Radius = 0.0115f, Height = 0.056f, RadialSegments = 10, Rings = 4 },
                Position = new Vector3(-side * 0.010f, 0.028f - f * 0.022f, -0.004f),
                RotationDegrees = new Vector3(0f, side * 18f, 90f),
                MaterialOverride = _gloveMat
            });
        }

        // Articulated Thumb wrapping inward toward DIFF/TORQ & top buttons
        hand.AddChild(new MeshInstance3D
        {
            Mesh = new CapsuleMesh { Radius = 0.014f, Height = 0.058f, RadialSegments = 10, Rings = 4 },
            Position = new Vector3(-side * 0.022f, 0.038f, 0.020f),
            RotationDegrees = new Vector3(-18f, side * 26f, side * 56f),
            MaterialOverride = _gloveMat
        });

        // Crisp White Nomex Elastic Wrist Cuff Band (exact signature detail from reference photo!)
        hand.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = 0.029f, BottomRadius = 0.033f, Height = 0.034f, RadialSegments = 14 },
            Position = new Vector3(side * 0.022f, -0.068f, 0.030f),
            RotationDegrees = new Vector3(36f, 0f, side * 18f),
            MaterialOverride = whiteCuffMat
        });

        // Fireproof Racing Suit Forearm extending organically down into the cockpit
        hand.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = 0.033f, BottomRadius = 0.044f, Height = 0.22f, RadialSegments = 14 },
            Position = new Vector3(side * 0.058f, -0.155f, 0.105f),
            RotationDegrees = new Vector3(44f, 0f, side * 22f),
            MaterialOverride = _sleeveMat
        });
    }

    public void UpdateColors(Color gloveColor, Color suitColor)
    {
        if (_gloveMat != null) _gloveMat.AlbedoColor = gloveColor;
        if (_sleeveMat != null) _sleeveMat.AlbedoColor = suitColor;
    }

    public void UpdateTelemetry(
        float dt,
        float speedKmh,
        int gear,
        int position,
        float rpmNorm,
        float lapTime,
        float bestLap,
        float ersCharge,
        bool ersActive,
        bool offTrack,
        float tireHeat,
        float totalTime)
    {
        // Trigger gear shift paddle kick animation on gear change
        if (gear != _prevGear && speedKmh > 25f)
        {
            _shiftWasUp = gear > _prevGear;
            _shiftKickTimer = 0.15f;
            _prevGear = gear;
        }
        if (_shiftKickTimer > 0f)
        {
            _shiftKickTimer = Mathf.Max(0f, _shiftKickTimer - dt);
        }

        float kick = _shiftKickTimer > 0f ? Mathf.Sin((_shiftKickTimer / 0.15f) * Mathf.Pi) * 14f : 0f;
        _paddleLeft.RotationDegrees = new Vector3(0f, !_shiftWasUp ? kick : 0f, 0f);
        _paddleRight.RotationDegrees = new Vector3(0f, _shiftWasUp ? -kick : 0f, 0f);

        // 15-LED Shift Light Bar (5 Green -> 5 Red -> 5 Blue, flashing at redline!)
        bool redlineFlash = rpmNorm > 0.93f && (((int)(totalTime * 16f) % 2) == 0);
        for (int i = 0; i < ShiftLedCount; i++)
        {
            bool lit = redlineFlash || ((i / (float)ShiftLedCount) < rpmNorm && speedKmh > 5f);
            Color c = i < 5 ? new Color(0.05f, 0.95f, 0.42f) : (i < 10 ? new Color(1.0f, 0.12f, 0.16f) : new Color(0.18f, 0.52f, 1.0f));
            _rpmLedMats[i].AlbedoColor = lit ? c : new Color(0.10f, 0.12f, 0.16f);
            _rpmLedMats[i].Emission = lit ? c : Colors.Black;
        }

        // Flanking 6 FIA Marshal / ERS LEDs
        Color flagCol = offTrack
            ? new Color(1.0f, 0.72f, 0.0f)
            : (ersActive ? new Color(0.0f, 0.92f, 1.0f) : new Color(0.05f, 0.85f, 0.42f));
        bool flagLit = offTrack || ersActive || speedKmh > 40f;
        for (int i = 0; i < _flagLedMats.Length; i++)
        {
            _flagLedMats[i].AlbedoColor = flagLit ? flagCol : new Color(0.10f, 0.12f, 0.16f);
            _flagLedMats[i].Emission = flagLit ? flagCol : Colors.Black;
        }

        // Live 512x288 OLED MFD Contents
        _mfdKph.Text = $"{(int)speedKmh}";
        _mfdLap.Text = lapTime < 60f
            ? $"{lapTime:00.000}"
            : $"{(int)(lapTime / 60f)}:{(lapTime % 60f):00.00}";
        _mfdPos.Text = $"P{position}";
        _mfdGear.Text = $"{gear}";
        _mfdGear.AddThemeColorOverride("font_color", redlineFlash ? new Color(0.45f, 0.88f, 1.0f) : Colors.White);

        if (bestLap < 900f)
        {
            float d = lapTime - bestLap;
            _mfdDelta.Text = d >= 0f ? $"+{d:0.00}" : $"{d:0.00}";
            _mfdDelta.AddThemeColorOverride("font_color", d <= 0f ? new Color(0.15f, 0.96f, 0.48f) : new Color(1.0f, 0.36f, 0.30f));
        }
        else
        {
            _mfdDelta.Text = "LIVE";
        }

        int fTemp = Mathf.RoundToInt(84f + tireHeat * 22f);
        int rTemp = Mathf.RoundToInt(87f + tireHeat * 20f);
        Color tCol = tireHeat > 0.75f ? new Color(1.0f, 0.78f, 0.32f) : new Color(0.90f, 0.97f, 0.92f);
        _mfdTempFL.Text = $"{fTemp}°C";
        _mfdTempFR.Text = $"{fTemp}°C";
        _mfdTempRL.Text = $"{rTemp}°C";
        _mfdTempRR.Text = $"{rTemp}°C";
        _mfdTempFL.AddThemeColorOverride("font_color", tCol);
        _mfdTempFR.AddThemeColorOverride("font_color", tCol);
        _mfdTempRL.AddThemeColorOverride("font_color", tCol);
        _mfdTempRR.AddThemeColorOverride("font_color", tCol);

        // Authentic 3-Zone Segmented F1 OVERTAKE Bar
        float frac = Mathf.Clamp(ersCharge / 100f, 0f, 1f);
        float totalW = 488f * frac;
        if (ersActive)
        {
            _ovtZoneRed.Visible = false;
            _ovtZoneYellow.Visible = false;
            _ovtZoneGreen.Visible = false;
            _ovtZoneCyan.Visible = true;
            _ovtZoneCyan.Size = new Vector2(Mathf.Max(4f, totalW), 62f);
        }
        else
        {
            _ovtZoneCyan.Visible = false;
            float w1 = Mathf.Min(totalW, 98f);
            float w2 = Mathf.Max(0f, Mathf.Min(totalW, 378f) - 98f);
            float w3 = Mathf.Max(0f, totalW - 378f);
            _ovtZoneRed.Visible = w1 > 1f;
            _ovtZoneYellow.Visible = w2 > 1f;
            _ovtZoneGreen.Visible = w3 > 1f;
            _ovtZoneRed.Size = new Vector2(w1, 62f);
            _ovtZoneYellow.Size = new Vector2(w2, 62f);
            _ovtZoneGreen.Size = new Vector2(w3, 62f);
        }

        _mfdOvtText.Text = offTrack
            ? "TRACK LIMITS"
            : (ersActive ? $"OVERTAKE ON  {(int)ersCharge}%" : $"OVERTAKE  {(int)ersCharge}%");
        _mfdOvtText.AddThemeColorOverride("font_color", frac > 0.24f ? new Color(0.04f, 0.06f, 0.10f) : Colors.White);
    }
}

scripts/AssetLoader3D.cs:
using Godot;
using System.Collections.Generic;

namespace ApexGP24;

public static class AssetLoader3D
{
    public static List<string> LoadedExternalAssets { get; } = new();

    public static void ResetLog()
    {
        LoadedExternalAssets.Clear();
    }

    public static string FindExistingPath(params string[] paths)
    {
        foreach (string p in paths)
        {
            if (ResourceLoader.Exists(p))
            {
                return p;
            }
        }
        return null;
    }

    public static Texture2D TryLoadTexture(string tag, params string[] paths)
    {
        string found = FindExistingPath(paths);
        if (found == null) return null;

        Texture2D tex = GD.Load<Texture2D>(found);
        if (tex != null && !LoadedExternalAssets.Contains(tag))
        {
            LoadedExternalAssets.Add(tag);
        }
        return tex;
    }

    /// <summary>
    /// Instantiates a user-uploaded .glb/.gltf model if present in res://assets/models/,
    /// automatically normalizing its scale & centering it to match real F1 dimensions!
    /// </summary>
    public static Node3D TryInstantiateGlb(string tag, float targetLengthOrWidth, bool alignBottomToZero, params string[] paths)
    {
        string found = FindExistingPath(paths);
        if (found == null) return null;

        PackedScene packed = GD.Load<PackedScene>(found);
        if (packed == null) return null;

        Node inst = packed.Instantiate();
        if (inst is not Node3D modelRoot)
        {
            inst?.QueueFree();
            return null;
        }

        var container = new Node3D { Name = $"CustomGlb_{tag}" };
        container.AddChild(modelRoot);

        if (TryComputeHierarchyAabb(modelRoot, Transform3D.Identity, out Aabb bounds))
        {
            float maxExtent = Mathf.Max(bounds.Size.X, Mathf.Max(bounds.Size.Y, bounds.Size.Z));
            if (maxExtent > 0.0001f)
            {
                float scaleFactor = targetLengthOrWidth / maxExtent;
                modelRoot.Scale = new Vector3(scaleFactor, scaleFactor, scaleFactor);

                Vector3 center = bounds.Position + bounds.Size * 0.5f;
                float offsetY = alignBottomToZero ? -bounds.Position.Y : -center.Y;
                modelRoot.Position = new Vector3(-center.X * scaleFactor, offsetY * scaleFactor, -center.Z * scaleFactor);
            }
        }

        if (!LoadedExternalAssets.Contains(tag))
        {
            LoadedExternalAssets.Add(tag);
        }
        return container;
    }

    private static bool TryComputeHierarchyAabb(Node node, Transform3D parentTransform, out Aabb combined)
    {
        combined = new Aabb();
        bool hasAny = false;

        Transform3D currentTransform = parentTransform;
        if (node is Node3D n3)
        {
            currentTransform = parentTransform * n3.Transform;
        }

        if (node is VisualInstance3D vis)
        {
            Aabb localBox = vis.GetAabb();
            if (localBox.Size.LengthSquared() > 0.000001f)
            {
                for (int i = 0; i < 8; i++)
                {
                    Vector3 corner = currentTransform * localBox.GetEndpoint(i);
                    if (!hasAny)
                    {
                        combined = new Aabb(corner, Vector3.Zero);
                        hasAny = true;
                    }
                    else
                    {
                        combined = combined.Expand(corner);
                    }
                }
            }
        }

        foreach (Node child in node.GetChildren())
        {
            if (TryComputeHierarchyAabb(child, currentTransform, out Aabb childBox))
            {
                if (!hasAny)
                {
                    combined = childBox;
                    hasAny = true;
                }
                else
                {
                    combined = combined.Merge(childBox);
                }
            }
        }

        return hasAny;
    }
}

scripts/F1AudioSynth.cs:
using Godot;
using System;

namespace ApexGP24;

public partial class F1AudioSynth : Node
{
    private const float SampleRate = 22050f;
    private AudioStreamPlayer _player;
    private AudioStreamGeneratorPlayback _playback;

    public bool Enabled { get; set; } = true;

    private float _rpm = 4200f;
    private float _speedKmh = 0f;
    private bool _throttle = false;
    private bool _brake = false;
    private bool _ers = false;
    private bool _onKerb = false;
    private bool _offTrack = false;

    private float _phase1 = 0f;
    private float _phase2 = 0f;
    private float _phase3 = 0f;
    private float _turboPhase = 0f;
    private float _kerbPhase = 0f;
    private float _shiftPopTimer = 0f;
    private int _prevGear = 1;
    private readonly Random _rng = new(1337);

    public override void _Ready()
    {
        var gen = new AudioStreamGenerator
        {
            MixRate = SampleRate,
            BufferLength = 0.08f
        };
        _player = new AudioStreamPlayer
        {
            Stream = gen,
            VolumeDb = -7.5f
        };
        AddChild(_player);
        _player.Play();
        _playback = _player.GetStreamPlayback() as AudioStreamGeneratorPlayback;
    }

    public void UpdateState(float rpm, float speedKmh, int gear, bool throttle, bool brake, bool ers, bool onKerb, bool offTrack)
    {
        if (gear != _prevGear && speedKmh > 30f)
        {
            _shiftPopTimer = 0.075f;
            _prevGear = gear;
        }
        _rpm = Mathf.Clamp(rpm, 3600f, 14500f);
        _speedKmh = speedKmh;
        _throttle = throttle;
        _brake = brake;
        _ers = ers;
        _onKerb = onKerb;
        _offTrack = offTrack;
    }

    public override void _Process(double delta)
    {
        if (_playback == null)
        {
            _playback = _player?.GetStreamPlayback() as AudioStreamGeneratorPlayback;
            if (_playback == null) return;
        }

        int frames = _playback.GetFramesAvailable();
        if (frames <= 0) return;

        if (!Enabled)
        {
            for (int i = 0; i < frames; i++)
            {
                _playback.PushFrame(Vector2.Zero);
            }
            return;
        }

        // V6 4-stroke firing frequency: 3 ignitions per rev -> rpm / 20 Hz!
        float fBase = _rpm / 20.0f;
        float inc1 = (fBase / SampleRate) * Mathf.Tau;
        float inc2 = (fBase * 1.5f / SampleRate) * Mathf.Tau;
        float inc3 = (fBase * 2.0f / SampleRate) * Mathf.Tau;
        float incTurbo = ((820f + (_rpm - 4000f) * 0.24f) / SampleRate) * Mathf.Tau;
        float incKerb = ((28f + _speedKmh * 0.22f) / SampleRate) * Mathf.Tau;

        float loadGain = _throttle ? 0.28f : (_brake ? 0.16f : 0.13f);
        float turboGain = (_throttle ? 0.045f : 0.015f) + (_ers ? 0.040f : 0f);
        float windGain = Mathf.Clamp(_speedKmh / 350f, 0f, 1f) * 0.055f;

        for (int i = 0; i < frames; i++)
        {
            _phase1 += inc1;
            _phase2 += inc2;
            _phase3 += inc3;
            _turboPhase += incTurbo;
            _kerbPhase += incKerb;

            if (_phase1 > Mathf.Tau) _phase1 -= Mathf.Tau;
            if (_phase2 > Mathf.Tau) _phase2 -= Mathf.Tau;
            if (_phase3 > Mathf.Tau) _phase3 -= Mathf.Tau;
            if (_turboPhase > Mathf.Tau) _turboPhase -= Mathf.Tau;
            if (_kerbPhase > Mathf.Tau) _kerbPhase -= Mathf.Tau;

            // Rich soft-clipped F1 V6 exhaust wave
            float rawEng =
                Mathf.Sin(_phase1) * 0.55f +
                Mathf.Sin(_phase2) * 0.30f +
                Mathf.Sin(_phase3) * 0.24f;
            float eng = Mathf.Tanh(rawEng * (_throttle ? 2.1f : 1.3f)) * loadGain;

            // Turbo / MGU-K electric whine
            float turbo = Mathf.Sin(_turboPhase) * turboGain;

            // Subtle aerodynamic rush & gravel/kerb texture
            float noise = ((float)_rng.NextDouble() * 2.0f - 1.0f);
            float aero = noise * windGain;
            float surface = 0f;
            if (_onKerb && _speedKmh > 25f)
            {
                surface = Mathf.Sin(_kerbPhase) * 0.11f;
            }
            else if (_offTrack && _speedKmh > 20f)
            {
                surface = noise * 0.09f;
            }

            // Crisp gear-shift exhaust crackle/cut
            float pop = 0f;
            if (_shiftPopTimer > 0f)
            {
                _shiftPopTimer -= 1.0f / SampleRate;
                eng *= 0.45f;
                pop = noise * 0.14f;
            }

            float sample = Mathf.Clamp(eng + turbo + aero + surface + pop, -0.85f, 0.85f);
            _playback.PushFrame(new Vector2(sample, sample));
        }
    }
}

scripts/RivalCar3D.cs:
using Godot;
using System;

namespace ApexGP24;

public struct RivalSpec
{
    public string Code;
    public string RearWingSponsor;
    public Color Primary;
    public Color Secondary;
    public Color Helmet;
    public Color TyreCompound;
    public float Skill;
}

public partial class RivalCar3D : Node3D
{
    // Shared procedural geometry & common materials across all 19 rivals (ultra-fast mobile FPS!)
    private static ArrayMesh _sharedNoseMesh;
    private static ArrayMesh _sharedHaloMesh;
    private static ArrayMesh _sharedFrontTireMesh;
    private static ArrayMesh _sharedRearTireMesh;
    private static ArrayMesh _sharedFrontDiscOut;
    private static ArrayMesh _sharedFrontDiscIn;
    private static ArrayMesh _sharedRearDiscOut;
    private static ArrayMesh _sharedRearDiscIn;
    private static StandardMaterial3D _sharedCarbonMat;
    private static StandardMaterial3D _sharedRubberMat;
    private static StandardMaterial3D _sharedSoftSidewall;
    private static StandardMaterial3D _sharedMedSidewall;
    private static StandardMaterial3D _sharedHardSidewall;
    private static StandardMaterial3D _sharedShadowMat;
    private static StandardMaterial3D _sharedRainLightOffMat;
    private static StandardMaterial3D _sharedRainLightOnMat;

    private TrackBuilder3D _track;
    public RivalSpec Spec { get; private set; }

    public float TrackDistance { get; set; }
    public float TotalDistance { get; set; }
    public float LateralOffset { get; set; }
    public float TargetLateral { get; set; }
    public float SpeedKmh { get; set; }
    public float LaunchDelay { get; set; }
    public bool IsBraking { get; private set; }
    public bool DrsOpen { get; private set; }

    private Vector3 _prevPos;
    private Basis _prevBasis = Basis.Identity;
    private Vector3 _currPos;
    private Basis _currBasis = Basis.Identity;

    private Node3D _drsFlapPivot;
    private MeshInstance3D _rainLightMesh;
    private readonly Node3D[] _wheelSpins = new Node3D[4];
    private float _wheelRoll = 0f;
    private float _smoothYaw = 0f;
    private float _drsAnim = 0f;
    private float _blinkTimer = 0f;
    private float _laneDecisionTimer = 0f;

    public static void EnsureSharedResources()
    {
        if (_sharedNoseMesh != null) return;

        _sharedNoseMesh = MeshPrimitives3D.CreateSculptedNoseconeMesh();
        Vector3[] haloPts =
        {
            new(-0.38f, 0.66f,  0.14f),
            new(-0.34f, 0.90f, -0.46f),
            new( 0.00f, 0.92f, -0.90f),
            new( 0.34f, 0.90f, -0.46f),
            new( 0.38f, 0.66f,  0.14f)
        };
        _sharedHaloMesh = MeshPrimitives3D.CreateTubeAlongPath(
            haloPts,
            new[] { 0.026f, 0.028f, 0.028f, 0.028f, 0.026f },
            new[] { 0.024f, 0.024f, 0.024f, 0.024f, 0.024f },
            8);

        _sharedFrontTireMesh = MeshPrimitives3D.CreateRevolvedTireTread(0.34f, 0.32f, 18);
        _sharedRearTireMesh = MeshPrimitives3D.CreateRevolvedTireTread(0.36f, 0.42f, 18);
        _sharedFrontDiscOut = MeshPrimitives3D.CreateTireSidewallDisc(0.29f, 0.16f, 1f, 16);
        _sharedFrontDiscIn = MeshPrimitives3D.CreateTireSidewallDisc(0.29f, -0.16f, -1f, 16);
        _sharedRearDiscOut = MeshPrimitives3D.CreateTireSidewallDisc(0.31f, 0.21f, 1f, 16);
        _sharedRearDiscIn = MeshPrimitives3D.CreateTireSidewallDisc(0.31f, -0.21f, -1f, 16);

        _sharedCarbonMat = ProceduralMaterialFactory.CreateCarbonMaterial(5.0f);
        _sharedRubberMat = ProceduralMaterialFactory.CreateTireRubberMaterial();
        _sharedSoftSidewall = ProceduralMaterialFactory.CreateTireSidewallMaterial(new Color(0.92f, 0.08f, 0.10f));
        _sharedMedSidewall = ProceduralMaterialFactory.CreateTireSidewallMaterial(new Color(0.98f, 0.82f, 0.08f));
        _sharedHardSidewall = ProceduralMaterial3DWhiteSidewall();
        _sharedShadowMat = new StandardMaterial3D
        {
            AlbedoColor = new Color(0f, 0f, 0f, 0.66f),
            Transparency = BaseMaterial3D.TransparencyEnum.Alpha,
            ShadingMode = BaseMaterial3D.ShadingModeEnum.Unshaded
        };
        _sharedRainLightOffMat = new StandardMaterial3D { AlbedoColor = new Color(0.25f, 0.04f, 0.05f), Roughness = 0.2f };
        _sharedRainLightOnMat = ProceduralMaterialFactory.CreateEmissiveMaterial(new Color(1.0f, 0.06f, 0.12f), 3.6f);
    }

    private static StandardMaterial3D ProceduralMaterial3DWhiteSidewall()
    {
        return ProceduralMaterialFactory.CreateTireSidewallMaterial(new Color(0.94f, 0.96f, 0.99f));
    }

    public void Initialize(TrackBuilder3D track, RivalSpec spec, float startDist, float startLane, float launchDelay)
    {
        EnsureSharedResources();
        _track = track;
        Spec = spec;
        LaunchDelay = launchDelay;
        BuildRivalMesh();
        ResetToGrid(startDist, startLane);
    }

    public void ResetToGrid(float startDist, float startLane)
    {
        TrackDistance = startDist;
        TotalDistance = startDist;
        LateralOffset = startLane;
        TargetLateral = startLane;
        SpeedKmh = 0f;
        IsBraking = false;
        DrsOpen = false;
        _smoothYaw = 0f;
        _drsAnim = 0f;
        ComputePose(out _currPos, out _currBasis);
        _prevPos = _currPos;
        _prevBasis = _currBasis;
        Position = _currPos;
        Basis = _currBasis;
    }

    private void BuildRivalMesh()
    {
        var primaryMat = ProceduralMaterialFactory.CreateCarPaintMaterial(Spec.Primary);
        var secondaryMat = ProceduralMaterialFactory.CreateCarPaintMaterial(Spec.Secondary);
        var helmetMat = ProceduralMaterialFactory.CreateCarPaintMaterial(Spec.Helmet);
        StandardMaterial3D sidewallMat = Spec.TyreCompound.G > 0.7f && Spec.TyreCompound.B > 0.7f
            ? _sharedHardSidewall
            : (Spec.TyreCompound.G > 0.6f ? _sharedMedSidewall : _sharedSoftSidewall);

        // Optional external Sketchfab Rival GLB if user uploaded assets/models/rival_car.glb!
