    public void StepPhysics(float dt, float raceTime, PlayerCar3D player, bool raceStarted)
    {
        _prevPos = _currPos;
        _prevBasis = _currBasis;

        if (!raceStarted || raceTime < LaunchDelay)
        {
            SpeedKmh = 0f;
            IsBraking = false;
            DrsOpen = false;
            UpdateVisuals(dt, 0f);
            return;
        }

        // Look ahead for upcoming corner curvature to brake smoothly & realistically!
        TrackSample sNow = _track.SampleAtDistance(TrackDistance);
        TrackSample sAhead = _track.SampleAtDistance(TrackDistance + 42f);
        TrackSample sFar = _track.SampleAtDistance(TrackDistance + 85f);

        float maxK = Mathf.Max(Mathf.Abs(sNow.Curvature), Mathf.Max(Mathf.Abs(sAhead.Curvature), Mathf.Abs(sFar.Curvature) * 0.85f));
        float baseTop = 285f + Spec.Skill * 42f;
        float cornerLimit = maxK < 0.0045f ? 345f : Mathf.Clamp(Mathf.Sqrt(74f / maxK) * 3.6f * (0.86f + Spec.Skill * 0.18f), 92f, 345f);
        float desiredSpeed = Mathf.Min(baseTop, cornerLimit);

        // Straightaway DRS deployment
        bool onStraight = Mathf.Abs(sNow.Curvature) < 0.0055f && Mathf.Abs(sAhead.Curvature) < 0.007f && SpeedKmh > 180f;
        DrsOpen = onStraight && desiredSpeed > 255f;
        if (DrsOpen) desiredSpeed = Mathf.Min(346f, desiredSpeed + 16f);

        // Subtle rubber-banding pack realism so the field stays exciting without feeling fake
        float distGapToPlayer = TotalDistance - player.TotalDistance;
        if (distGapToPlayer > 240f) desiredSpeed *= 0.94f;
        else if (distGapToPlayer < -240f) desiredSpeed *= 1.05f;

        // Avoid rear-ending or sideswiping player smoothly
        float dzToPlayer = player.TotalDistance - TotalDistance;
        float dxToPlayer = player.LateralOffset - LateralOffset;
        _laneDecisionTimer -= dt;
        if (dzToPlayer > 1.5f && dzToPlayer < 24f && Mathf.Abs(dxToPlayer) < 2.6f)
        {
            float evadeDir = player.LateralOffset > 0f ? -1f : 1f;
            TargetLateral = Mathf.Clamp(player.LateralOffset + evadeDir * 3.2f, -TrackBuilder3D.TrackHalfWidth + 1.4f, TrackBuilder3D.TrackHalfWidth - 1.4f);
            if (dzToPlayer < 10.5f && Mathf.Abs(dxToPlayer) < 2.2f)
            {
                desiredSpeed = Mathf.Min(desiredSpeed, Mathf.Max(40f, player.SpeedKmh - 12f));
            }
        }
        else if (_laneDecisionTimer <= 0f)
        {
            _laneDecisionTimer = 1.6f + (Spec.Skill * 1.1f);
            float idealX = Mathf.Clamp(sNow.Curvature * 175f, -TrackBuilder3D.TrackHalfWidth * 0.65f, TrackBuilder3D.TrackHalfWidth * 0.65f);
            TargetLateral = Mathf.Clamp(idealX + (Spec.Skill - 0.88f) * 8.0f, -TrackBuilder3D.TrackHalfWidth + 1.4f, TrackBuilder3D.TrackHalfWidth - 1.4f);
        }

        if (desiredSpeed > SpeedKmh)
        {
            float acc = (106f + Spec.Skill * 24f) + (DrsOpen ? 22f : 0f);
            SpeedKmh = Mathf.Min(desiredSpeed, SpeedKmh + acc * dt);
            IsBraking = false;
        }
        else
        {
            SpeedKmh = Mathf.Max(desiredSpeed, SpeedKmh - 185f * dt);
            IsBraking = (SpeedKmh - desiredSpeed) > 10f;
        }

        float vMs = SpeedKmh / 3.6f;
        float prevLat = LateralOffset;
        LateralOffset = Mathf.Lerp(LateralOffset, TargetLateral, 1f - Mathf.Exp(-3.4f * dt));
        float latVel = (LateralOffset - prevLat) / Mathf.Max(dt, 0.005f);
        float targetYaw = Mathf.Clamp(Mathf.Atan2(latVel, Mathf.Max(vMs, 8f)), -0.28f, 0.28f);
        _smoothYaw = Mathf.Lerp(_smoothYaw, targetYaw, 1f - Mathf.Exp(-8.5f * dt));

        float advance = vMs * dt;
        TotalDistance += advance;
        TrackDistance += advance;
        if (TrackDistance >= _track.TotalLength) TrackDistance -= _track.TotalLength;

        ComputePose(out _currPos, out _currBasis);
        UpdateVisuals(dt, vMs);
    }

    private void UpdateVisuals(float dt, float vMs)
    {
        _wheelRoll -= vMs * dt / 0.35f;
        for (int w = 0; w < 4; w++)
        {
            if (_wheelSpins[w] != null) _wheelSpins[w].Rotation = new Vector3(_wheelRoll, 0f, 0f);
        }

        if (_drsFlapPivot != null)
        {
            _drsAnim = Mathf.Lerp(_drsAnim, DrsOpen ? 1f : 0f, 1f - Mathf.Exp(-12f * dt));
            _drsFlapPivot.RotationDegrees = new Vector3(-55f * _drsAnim, 0f, 0f);
        }

        if (_rainLightMesh != null)
        {
            _blinkTimer += dt;
            bool blinkOn = IsBraking || (SpeedKmh > 120f && ((int)(_blinkTimer * 5f) % 2 == 0));
            _rainLightMesh.MaterialOverride = blinkOn ? _sharedRainLightOnMat : _sharedRainLightOffMat;
        }
    }

    private void ComputePose(out Vector3 pos, out Basis basis)
    {
        TrackSample s = _track.SampleAtDistance(TrackDistance);
        pos = s.Center + s.Right * LateralOffset + Vector3.Up * 0.04f;
        basis = Basis.LookingAt(s.Forward, Vector3.Up).Rotated(Vector3.Up, -_smoothYaw);
    }

    public void ApplyInterpolatedPose(float alpha)
    {
        Position = _prevPos.Lerp(_currPos, alpha);
        Basis = _prevBasis.Slerp(_currBasis, alpha);
    }
